import * as React from "react";
import { Box, Grid, Card, CardContent, Typography, Modal, Button } from "@mui/material";
import axios from "axios";

// Define types for venue and availability
interface Venue {
  title: string;
  subtitle: string;
  description: string;
  vendorId: number;
}

export default function VenuesPage() {
  const [selectedVenue, setSelectedVenue] = React.useState<Venue | null>(null);
  const [availableVenues, setAvailableVenues] = React.useState<Venue[]>([]);

  // Fetch available venues based on the selected date
  const fetchAvailableVenues = async () => {
    const selectedDate = localStorage.getItem("selectedDate");  // Retrieve date from local storage

    if (selectedDate) {
      try {
        const response = await axios.get(`/api/available-venues?date=${selectedDate}`);
        setAvailableVenues(response.data);
      } catch (error) {
        console.error("Error fetching available venues:", error);
      }
    }
  };

  // Call the fetch function when the component mounts
  React.useEffect(() => {
    fetchAvailableVenues();
  }, []);

  const handleOpen = (venue: Venue) => {
    setSelectedVenue(venue);
  };

  const handleClose = () => {
    setSelectedVenue(null);
  };

  return (
    <Box sx={{ width: "100%", minHeight: "100vh", backgroundColor: "#f5f5f5", padding: 2 }}>
      <Typography variant="h4" sx={{ fontWeight: "bold", marginBottom: 3, textAlign: "center" }}>
        Explore Venues
      </Typography>

      {/* Grid Layout for Boxes */}
      <Grid container spacing={2} sx={{ justifyContent: "center" }}>
        {availableVenues.map((venue, index) => (
          <Grid item xs={6} key={index}>
            <Card
              sx={{
                borderRadius: 6,
                boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
                overflow: "hidden",
                backgroundColor: "transparent",
                display: "flex",
                flexDirection: "column",
                height: "100%",
              }}
              onClick={() => handleOpen(venue)}
            >
              <Box sx={{ width: "100%", aspectRatio: "4 / 3", backgroundColor: "#d0e7ff" }} />
              <CardContent sx={{ paddingTop: 2, backgroundColor: "#fff", height: "calc(1 / 6 * 100%)", marginTop: "auto" }}>
                <Typography variant="h6" sx={{ fontWeight: "bold", textAlign: "center", overflow: "hidden", textOverflow: "ellipsis" }}>
                  {venue.title}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ textAlign: "center", marginTop: 1 }}>
                  {venue.subtitle}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Modal for displaying venue details */}
      <Modal open={!!selectedVenue} onClose={handleClose} sx={{ display: "flex", justifyContent: "center", alignItems: "center" }}>
        <Box sx={{ width: "85%", backgroundColor: "white", padding: 3, borderRadius: 2, height: "40%", overflowY: "auto", position: "relative" }}>
          <Button onClick={handleClose} sx={{ position: "absolute", top: 10, right: 10, fontSize: "1.5rem", backgroundColor: "transparent", color: "black" }}>
            X
          </Button>
          <Typography variant="h4" sx={{ fontWeight: "bold" }}>{selectedVenue?.title}</Typography>
          <Typography variant="body1" sx={{ marginBottom: 2 }}>{selectedVenue?.description}</Typography>
          <Box sx={{ position: "absolute", bottom: 10, right: 10 }}>
            <Button variant="contained" sx={{ backgroundColor: "#F7C5AD", color: "#000", '&:hover': { backgroundColor: "#f7b59b" }, padding: "8px 20px" }}>
              Book
            </Button>
          </Box>
        </Box>
      </Modal>
    </Box>
  );
}


